def safe_num(val):
    return float(str(val).strip().replace(',', ''))

def normalized_header_name(h):
    return ''.join(ch.lower() for ch in str(h) if ch.isalnum())

def detect_fields(csv_path):
    with open(csv_path, 'r', newline='', encoding='utf-8-sig') as f:
        header = next(csv.reader(f))
    norm_map = {normalized_header_name(h): h for h in header}
    x = y = z = None
    for k,h in norm_map.items():
        if x is None and (k in ('e','x','east','easting') or 'east' in k): x = h
        if y is None and (k in ('n','y','north','northing') or 'north' in k): y = h
        if z is None and (k in ('z','rl') or 'elev' in k or 'level' in k or k == 'height'): z = h
    return x, y, z

def make_points(csv_path, fc_name):
    x_field, y_field, z_field = detect_fields(csv_path)
    if not (x_field and y_field and z_field):
        raise RuntimeError('Missing usable X/Y/Z fields in ' + csv_path)
