    arcpy.management.AddField(fc, 'Z_VAL', 'DOUBLE')
    cnt = 0
    with open(csv_path, 'r', newline='', encoding='utf-8-sig') as f:
        rdr = csv.DictReader(f)
        with arcpy.da.InsertCursor(fc, ['SRC_ID', 'Z_VAL', 'SHAPE@XYZ']) as ic:
            oid = 1
